import { afterEach, describe, expect, it, vi } from "vitest";
import { migrateLocalLibrary, type HistoryMeta } from "../history";

const FLAG = "ask3d:library-migrated-v1";
const DATABASE = "ask3d-history";

type ReadFailure = "request error" | "transaction exception" | "read exception";
type BlobFailure = ReadFailure | "missing bytes";
type UploadFailure = "HTTP error" | "network rejection";
type EventName = "success" | "error" | "complete" | "abort";
type Handler = ((event: Event) => void) | null;

// Deliver request events asynchronously, like IndexedDB, and support both
// event listeners and on-event properties. No history functions are mocked.
class DatabaseEvents extends EventTarget {
  onsuccess: Handler = null;
  onerror: Handler = null;
  oncomplete: Handler = null;
  onabort: Handler = null;
  error: DOMException | null = null;

  emit(name: EventName) {
    const event = new Event(name, { cancelable: true });
    this.dispatchEvent(event);
    this[`on${name}`]?.call(this, event);
  }
}

class ReadRequest<T> extends DatabaseEvents {
  result!: T;
  constructor(public transaction: DatabaseEvents | null = null) {
    super();
  }
}

function readRequest<T>(value: T, fails: boolean, transaction: DatabaseEvents | null = null) {
  const request = new ReadRequest<T>(transaction);
  queueMicrotask(() => {
    if (fails) {
      request.error = new DOMException("Injected read failure", "UnknownError");
      request.emit("error");
      if (transaction) {
        transaction.error = request.error;
        transaction.emit("error");
        transaction.emit("abort");
      }
    } else {
      request.result = value;
      request.emit("success");
      queueMicrotask(() => transaction?.emit("complete"));
    }
  });
  return request;
}

function item(id: string, createdAt: number, extra: Partial<HistoryMeta> = {}): HistoryMeta {
  return {
    id,
    createdAt,
    kind: "mesh",
    name: `${id}.stl`,
    mime: "model/stl",
    size: 3,
    ...extra,
  };
}

function key(meta: Pick<HistoryMeta, "kind" | "name">) {
  return JSON.stringify([meta.kind, meta.name]);
}

function browser(localItems: HistoryMeta[], sharedItems: HistoryMeta[] = []) {
  const local = new Map(localItems.map((meta) => [meta.id, { ...meta }]));
  const blobs = new Map(localItems.map((meta, index) => [meta.id, new Uint8Array([index + 1, 0, 255]).buffer]));
  const shared = new Map(sharedItems.map((meta) => [key(meta), { ...meta }]));
  const storage = new Map<string, string>();
  const state = {
    openError: false,
    storageReadable: true,
    metaFailure: null as ReadFailure | null,
    blobFailure: null as BlobFailure | null,
    blobFailureId: localItems.at(-1)?.id,
    uploadFailure: null as UploadFailure | null,
    uploadFailureName: localItems.at(-1)?.name,
    databaseExists: true,
    openCalls: 0,
    liveConnections: 0,
    deleteCalls: 0,
    listCalls: 0,
    blobReads: [] as string[],
    uploads: [] as { meta: Omit<HistoryMeta, "id" | "createdAt" | "size">; bytes: number[]; accepted: boolean }[],
    finalizations: [] as { operation: string; unshared: string[] }[],
    unexpected: [] as string[],
  };
  const unshared = () => [...local.values()].filter((meta) => !shared.has(key(meta))).map((meta) => meta.id);

  function connection() {
    let closed = false;
    state.liveConnections += 1;
    return {
      close() {
        if (!closed) state.liveConnections -= 1;
        closed = true;
      },
      transaction(storeName: string | string[], mode: string = "readonly") {
        const names = typeof storeName === "string" ? [storeName] : storeName;
        if (closed) throw new DOMException("Closed database", "InvalidStateError");
        if (mode !== "readonly" || names.some((name) => name !== "meta" && name !== "blobs")) {
          state.unexpected.push(`transaction ${names.join(",")} ${mode}`);
          throw new DOMException("Unexpected transaction", "NotFoundError");
        }
        if ((names.includes("meta") && state.metaFailure === "transaction exception") ||
            (names.includes("blobs") && state.blobFailure === "transaction exception")) {
          throw new DOMException("Injected transaction failure", "InvalidStateError");
        }
        const transaction: DatabaseEvents & {
          abort(): void;
          objectStore(name: string): {
            getAll(): ReadRequest<HistoryMeta[]>;
            get(id: string): ReadRequest<ArrayBuffer | undefined>;
          };
        } = Object.assign(new DatabaseEvents(), {
          abort() {
            transaction.error = new DOMException("Aborted", "AbortError");
            transaction.emit("abort");
          },
          objectStore(name: string) {
            if (!names.includes(name)) throw new DOMException("Wrong store", "NotFoundError");
            return {
              getAll() {
                if (name !== "meta") throw new DOMException("Wrong store", "NotFoundError");
                if (state.metaFailure === "read exception") {
                  throw new DOMException("Injected metadata read failure", "InvalidStateError");
                }
                return readRequest([...local.values()].map((meta) => ({ ...meta })), state.metaFailure === "request error", transaction);
              },
              get(id: string) {
                if (name !== "blobs") throw new DOMException("Wrong store", "NotFoundError");
                state.blobReads.push(id);
                const failure = id === state.blobFailureId ? state.blobFailure : null;
                if (failure === "read exception") {
                  throw new DOMException("Injected blob read failure", "InvalidStateError");
                }
                const bytes = failure === "missing bytes" ? undefined : blobs.get(id)?.slice(0);
                return readRequest(bytes, failure === "request error", transaction);
              },
            };
          },
        });
        return transaction;
      },
    };
  }

  vi.stubGlobal("localStorage", {
    getItem(name: string) {
      if (!state.storageReadable) throw new DOMException("Storage unavailable", "SecurityError");
      return storage.get(name) ?? null;
    },
    setItem(name: string, value: string) {
      if (name === FLAG) state.finalizations.push({ operation: "flag", unshared: unshared() });
      storage.set(name, value);
    },
    removeItem(name: string) {
      storage.delete(name);
    },
  });
  vi.stubGlobal("indexedDB", {
    open(name: string, version?: number) {
      state.openCalls += 1;
      if (name !== DATABASE || (version !== undefined && version !== 1)) state.unexpected.push(`open ${name} ${version}`);
      // The selected tests start with an existing database. Deleting it before
      // success must not be hidden by recreating the fixture on the retry.
      if (state.openError || !state.databaseExists) return readRequest(undefined, true);
      return readRequest(connection(), false);
    },
    deleteDatabase(name: string) {
      state.deleteCalls += 1;
      if (name !== DATABASE) state.unexpected.push(`delete ${name}`);
      state.finalizations.push({ operation: "delete", unshared: unshared() });
      if (state.liveConnections === 0) {
        state.databaseExists = false;
        local.clear();
        blobs.clear();
      }
      return readRequest(undefined, false);
    },
  });
  vi.stubGlobal("fetch", vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = input instanceof Request ? input.url : String(input);
    const method = init?.method ?? "GET";
    if (url !== "/api/library") {
      state.unexpected.push(`${method} ${url}`);
      return new Response(null, { status: 404 });
    }
    if (method === "GET") {
      state.listCalls += 1;
      return Response.json({ items: [...shared.values()] });
    }
    if (method !== "POST" || !(init?.body instanceof FormData)) {
      state.unexpected.push(`${method} without library form data`);
      return new Response(null, { status: 400 });
    }
    const metaField = init.body.get("meta");
    const blobField = init.body.get("bytes");
    if (typeof metaField !== "string" || !(blobField instanceof Blob)) {
      state.unexpected.push("invalid upload fields");
      return new Response(null, { status: 400 });
    }
    const meta = JSON.parse(metaField) as Omit<HistoryMeta, "id" | "createdAt" | "size">;
    const bytes = [...new Uint8Array(await blobField.arrayBuffer())];
    const failure = meta.name === state.uploadFailureName ? state.uploadFailure : null;
    state.uploads.push({ meta, bytes, accepted: failure === null });
    if (failure === "network rejection") throw new TypeError("Injected network failure");
    if (failure === "HTTP error") return new Response(null, { status: 503 });
    shared.set(key(meta), { ...meta, id: `shared-${state.uploads.length}`, createdAt: 1000 + state.uploads.length, size: bytes.length });
    return Response.json({ id: shared.get(key(meta))!.id });
  }));
  vi.spyOn(console, "warn").mockImplementation(() => {});
  vi.spyOn(console, "info").mockImplementation(() => {});

  return { state, storage, local, blobs, shared };
}

function expectPending(harness: ReturnType<typeof browser>, originals: HistoryMeta[]) {
  expect(harness.storage.get(FLAG)).toBeUndefined();
  expect(harness.state.finalizations).toEqual([]);
  expect(harness.state.deleteCalls).toBe(0);
  expect(harness.state.databaseExists).toBe(true);
  expect([...harness.local.values()]).toEqual(originals);
  expect(harness.blobs.size).toBe(originals.length);
  expect(harness.state.liveConnections).toBe(0);
  expect(harness.state.unexpected).toEqual([]);
}

function expectComplete(harness: ReturnType<typeof browser>, originals: HistoryMeta[]) {
  expect(harness.storage.get(FLAG)).toBe("1");
  expect(harness.state.deleteCalls).toBe(1);
  expect(harness.state.databaseExists).toBe(false);
  expect(harness.state.liveConnections).toBe(0);
  expect(harness.state.finalizations.map((event) => event.operation).sort()).toEqual(["delete", "flag"]);
  expect(harness.state.finalizations.every((event) => event.unshared.length === 0)).toBe(true);
  for (const meta of originals) expect(harness.shared.has(key(meta))).toBe(true);
  expect(harness.state.unexpected).toEqual([]);
}

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("local library migration", () => {
  it("retries an open error and completes only after the items are shared", async () => {
    const oldest = item("oldest", 10, { dims: { x: 3, y: 4, z: 5 }, note: "original import" });
    const newest = item("newest", 30, { kind: "compiled", prompt: "make a cube", scad: "cube(5);" });
    const sameName = item("local-image", 20, { kind: "image", name: oldest.name, mime: "image/png", thumb: "data:image/png;base64,AA==" });
    const known = item("local-known", 5);
    const originals = [newest, known, sameName, oldest];
    const sharedKnown = { ...known, id: "server-known", createdAt: 99 };
    const harness = browser(originals, [sharedKnown, item("same-name-on-server", 1, { kind: "statue", name: oldest.name })]);
    // Unreadable storage is still a no-op, before any IndexedDB access.
    harness.state.storageReadable = false;
    await migrateLocalLibrary();
    expect(harness.state.openCalls).toBe(0);
    expect(harness.state.listCalls).toBe(0);
    expectPending(harness, originals);

    harness.state.storageReadable = true;
    harness.state.openError = true;
    await migrateLocalLibrary();
    expect(harness.state.openCalls).toBe(1);
    expectPending(harness, originals);
    expect(harness.state.uploads).toEqual([]);

    harness.state.openError = false;
    await migrateLocalLibrary();
    expectComplete(harness, originals);
    expect(harness.state.openCalls).toBe(2);
    expect(harness.state.blobReads).not.toContain(known.id);
    expect(harness.shared.get(key(known))).toEqual(sharedKnown);
    expect(harness.state.uploads).toEqual([
      { meta: { kind: oldest.kind, name: oldest.name, mime: oldest.mime, dims: oldest.dims, note: oldest.note }, bytes: [4, 0, 255], accepted: true },
      { meta: { kind: sameName.kind, name: sameName.name, mime: sameName.mime, thumb: sameName.thumb }, bytes: [3, 0, 255], accepted: true },
      { meta: { kind: newest.kind, name: newest.name, mime: newest.mime, prompt: newest.prompt, scad: newest.scad }, bytes: [1, 0, 255], accepted: true },
    ]);
    await migrateLocalLibrary();
    expect(harness.state.openCalls).toBe(2);
    expect(harness.state.uploads).toHaveLength(3);
    expectComplete(harness, originals);
  });

  it.each(["request error", "transaction exception", "read exception"] as const)(
    "preserves and retries metadata after %s",
    async (failure) => {
      const originals = [item("only", 10)];
      const harness = browser(originals);
      harness.state.metaFailure = failure;
      await migrateLocalLibrary();
      expectPending(harness, originals);
      expect(harness.state.uploads).toEqual([]);

      harness.state.metaFailure = null;
      await migrateLocalLibrary();
      expectComplete(harness, originals);
      expect(harness.state.openCalls).toBe(2);
      expect(harness.state.uploads.map((upload) => upload.meta.name)).toEqual(["only.stl"]);
      expect(harness.state.uploads[0].bytes).toEqual([1, 0, 255]);
    },
  );

  it.each(["missing bytes", "request error", "transaction exception", "read exception"] as const)(
    "preserves and retries an unreadable item after %s",
    async (failure) => {
      const originals = [item("first", 10), item("unreadable", 20)];
      const harness = browser(originals);
      harness.state.blobFailure = failure;
      await migrateLocalLibrary();
      expectPending(harness, originals);
      const sharedBeforeRetry = new Set(harness.shared.keys());
      const attemptsBeforeRetry = harness.state.uploads.length;

      harness.state.blobFailure = null;
      await migrateLocalLibrary();
      expectComplete(harness, originals);
      expect(harness.state.openCalls).toBe(2);
      expect(harness.state.uploads.map((upload) => upload.meta.name)).toEqual(["first.stl", "unreadable.stl"]);
      expect(harness.state.uploads.map((upload) => upload.bytes)).toEqual([[1, 0, 255], [2, 0, 255]]);
      expect(harness.state.uploads.slice(attemptsBeforeRetry).some((upload) => sharedBeforeRetry.has(key(upload.meta)))).toBe(false);
    },
  );

  it.each(["HTTP error", "network rejection"] as const)(
    "retries only the unshared item after %s",
    async (failure) => {
      const originals = [item("first", 10), item("failed", 20)];
      const harness = browser(originals);
      harness.state.uploadFailure = failure;
      await migrateLocalLibrary();
      expectPending(harness, originals);
      expect(harness.shared.has(key(originals[0]))).toBe(true);
      expect(harness.shared.has(key(originals[1]))).toBe(false);
      expect(harness.state.uploads.map((upload) => upload.accepted)).toEqual([true, false]);

      harness.state.uploadFailure = null;
      await migrateLocalLibrary();
      expectComplete(harness, originals);
      expect(harness.state.openCalls).toBe(2);
      expect(harness.state.uploads.map((upload) => upload.meta.name)).toEqual(["first.stl", "failed.stl", "failed.stl"]);
      expect(harness.state.uploads.map((upload) => upload.accepted)).toEqual([true, false, true]);
      expect(harness.state.uploads[2].bytes).toEqual([2, 0, 255]);
    },
  );
});
